uniform float iZoom;
uniform float iOpacity;

// uniforms: iResolution, iTime, iMouse

float smoothMin(float a, float b, float k) {
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);

    return mix(b, a, h) - k * h * (1.0 - h);
}

float sdf(vec2 position) {
    float dist = 0.0;
    float iPetal = 0.76;

    // Describing the background image scene
    vec2 p = position * iZoom;

    p = vec2(p.x + p.y, p.x - p.y);
    p = mod(p + 1.0, 2.0) - 1.0;
    p = abs(p);

    float distA = length(p) - 0.2;
    float distB = length(0.4 - p) - 0.36;
    float distC = max(p.x - iPetal, 0.4 - p.x);
    float distD = max(p.y - iPetal, 0.4 - p.y);
    float distE = max(distC, distD);
    float distF = min(distE, distB);
    float distG = 0.3 - length(p);
    float distH = max(distF, distG);
    float distI = min(distA, distH);

    // This is the final combined distance from your original logic
    dist = distI;

    return dist;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Standardize coordinates (-0.5 to 0.5 range on the Y axis)
    vec2 position = (fragCoord.xy - iResolution.xy / 2.0) / iResolution.yy;

    // Find the distance
    float dist = sdf(position);

    // Shading used in the background
    float colorVal = sin(position.x * 0.3 + 0.2) + sin((1.0 - position.y) * 0.7 - 0.2) + 0.1;

    if (dist <= 0.0) {
        colorVal *= 1.0 + exp(dist * iOpacity) * 0.2;
    }

    // Final color output
    fragColor = vec4(vec3(
        colorVal, 
        colorVal * 0.5, 
        sin(colorVal / 3.0 + position.x - position.y) * 0.75
    ), 1.0);
}

noDrag()
noOutput()
setPortCount(0, 1)
setTitle("xy.pad")

let padX = width / 2
let padY = height / 2
let isDragging = false

// Receive messages to set position
recv(m => {
  let x, y

  if (Array.isArray(m)) {
    if (typeof m[0] === 'number') x = m[0]
    if (typeof m[1] === 'number') y = m[1]
  } else if (typeof m === 'object') {
    if ('x' in m) x = m.x
    if ('y' in m) y = m.y
   } else return

  if (x !== undefined) {
    padX = x * width
  }

  if (y !== undefined) {
    padY = y * height
  }

  send([padX / width, padY / height])
})

function draw() {
  ctx.fillStyle = '#18181b'
  ctx.fillRect(0, 0, width, height)

  // Grid
  ctx.strokeStyle = '#27272a'
  ctx.lineWidth = 1

  for (let i = 1; i < 4; i++) {
    const x = (width / 4) * i
    const y = (height / 4) * i
    ctx.beginPath()
    ctx.moveTo(x, 0)
    ctx.lineTo(x, height)
    ctx.stroke()
    ctx.beginPath()
    ctx.moveTo(0, y)
    ctx.lineTo(width, y)
    ctx.stroke()
  }

  // Center crosshair
  ctx.strokeStyle = '#3f3f46'
  ctx.lineWidth = 2
  ctx.beginPath()
  ctx.moveTo(width / 2 - 10, height / 2)
  ctx.lineTo(width / 2 + 10, height / 2)
  ctx.moveTo(width / 2, height / 2 - 10)
  ctx.lineTo(width / 2, height / 2 + 10)
  ctx.stroke()

  // Update position on drag
  if (mouse.down) {
    padX = mouse.x
    padY = mouse.y
    isDragging = true

    // Send normalized coordinates (0-1)
    send([padX / width, padY / height])
  } else if (isDragging) {
    isDragging = false
  }

  // Draw position indicator
  ctx.fillStyle = mouse.down ? '#4ade80' : '#71717a'
  ctx.beginPath()
  ctx.arc(padX, padY, 12, 0, Math.PI * 2)
  ctx.fill()

  // Draw crosshair on position
  ctx.strokeStyle = '#fff'
  ctx.lineWidth = 2
  ctx.beginPath()
  ctx.moveTo(padX - 20, padY)
  ctx.lineTo(padX + 20, padY)
  ctx.moveTo(padX, padY - 20)
  ctx.lineTo(padX, padY + 20)
  ctx.stroke()

  requestAnimationFrame(draw)
}

draw()

setPortCount(1, 2)
setRunOnMount(true)

recv(([x, y]) => {
  send(x*16, {to: 0})
  send(y*16, {to: 1})
})
